-- V4: Ensure at least 5 hotels per city in demo dataset (adds to V2+V3).


SELECT r.id, CURRENT_DATE + s.n, 4, 4
FROM rooms r
JOIN hotels h ON h.id = r.hotel_id
CROSS JOIN generate_series(0, 90) AS s(n)
WHERE h.name IN ('Cappadocia Vista Hotel V4-200', 'Cappadocia Vista Hotel V4-201', 'Cappadocia Vista Hotel V4-202', 'Cappadocia Vista Hotel V4-203', 'Bursa Vista Hotel V4-204', 'Bursa Vista Hotel V4-205', 'Bursa Vista Hotel V4-206', 'Bodrum Vista Hotel V4-207', 'Bodrum Vista Hotel V4-208', 'Fethiye Vista Hotel V4-209', 'Fethiye Vista Hotel V4-210', 'Fethiye Vista Hotel V4-211', 'Marmaris Vista Hotel V4-212', 'Marmaris Vista Hotel V4-213', 'Marmaris Vista Hotel V4-214', 'Trabzon Vista Hotel V4-215', 'Trabzon Vista Hotel V4-216', 'Trabzon Vista Hotel V4-217', 'Gaziantep Vista Hotel V4-218', 'Gaziantep Vista Hotel V4-219', 'Gaziantep Vista Hotel V4-220', 'Konya Vista Hotel V4-221', 'Konya Vista Hotel V4-222', 'Konya Vista Hotel V4-223', 'Nevsehir Vista Hotel V4-224', 'Nevsehir Vista Hotel V4-225', 'Nevsehir Vista Hotel V4-226', 'Canakkale Vista Hotel V4-227', 'Canakkale Vista Hotel V4-228', 'Canakkale Vista Hotel V4-229', 'Canakkale Vista Hotel V4-230', 'Adana Vista Hotel V4-231', 'Adana Vista Hotel V4-232', 'Adana Vista Hotel V4-233', 'Denizli Vista Hotel V4-234', 'Denizli Vista Hotel V4-235', 'Denizli Vista Hotel V4-236', 'Eskisehir Vista Hotel V4-237', 'Eskisehir Vista Hotel V4-238', 'Eskisehir Vista Hotel V4-239', 'Eskisehir Vista Hotel V4-240', 'Rize Vista Hotel V4-241', 'Rize Vista Hotel V4-242', 'Rize Vista Hotel V4-243', 'Rize Vista Hotel V4-244', 'Mersin Vista Hotel V4-245', 'Mersin Vista Hotel V4-246', 'Mersin Vista Hotel V4-247', 'Mersin Vista Hotel V4-248', 'Kayseri Vista Hotel V4-249', 'Kayseri Vista Hotel V4-250', 'Kayseri Vista Hotel V4-251', 'Kayseri Vista Hotel V4-252');